plans:
companies_str = get_all_car_rental_companies_in_city(city="Los Angeles")
companies = ask(value=companies_str, question="List the names of all car rental companies mentioned in this text.", type="list[str]")

suv_companies = []
for c in companies:
    types_info = get_car_types_available(company_name=c)
    has_suv = ask(value=types_info, question="Does this information say SUV car types are available? Answer true or false.", type="bool")
    if has_suv:
        suv_companies.append(c)

if len(suv_companies) == 0:
    respond("Sorry, I couldn't find any car rental companies in Los Angeles with SUVs available for your December 15 pickup.")
else:
    best_name = ""
    best_score = -1.0
    for c in suv_companies:
        rating_info = get_rating_reviews_for_car_rental(company_name=c)
        score = ask(value=rating_info, question="What is the overall numeric rating for this company? Answer with a number only.", type="float")
        if score > best_score:
            best_score = score
            best_name = c
    respond("Car rental companies in Los Angeles with SUVs available: " + ", ".join(suv_companies) + ". The highest rated is " + best_name + " with a rating of " + str(best_score) + ".")
